function startLiveActivity(items) {
  if (liveActivityTimer) clearInterval(liveActivityTimer);
  if (!items.length || window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  let index = 0;
  const advance = () => {
    document.querySelectorAll('.live-feed-row').forEach((row) => row.classList.toggle('active', Number(row.dataset.feedIndex) === index));
    const current = items[index];
    const countries = current.countries || [current.country].filter(Boolean);
    document.querySelectorAll('.map-pulse').forEach((marker) => marker.classList.toggle('active', countries.includes(marker.dataset.country)));
    document.querySelectorAll('.map-flow').forEach((flow) => flow.classList.toggle('active', Number(flow.dataset.flowIndex) === index));
    const row = document.querySelector(`.live-feed-row[data-feed-index="${index}"]`);
    const feed = document.querySelector('#live-attacker-feed');
    if (row && feed) feed.scrollTo({ top: Math.max(0, row.offsetTop - feed.offsetTop - 8), behavior: 'smooth' });
    index = (index + 1) % items.length;
  };
  advance();
  liveActivityTimer = setInterval(advance, 1900);
}

function mapCoordinates(code) {
  const [longitude, latitude] = countryCentroids[code];
  return { x: (longitude + 180) / 360 * 1000, y: (90 - latitude) / 180 * 500 };
}

function mapPulse(code, size, type, title) {
  const { x, y } = mapCoordinates(code);
  return `<span class="map-pulse ${type}" data-country="${escapeHtml(code)}" style="--map-x:${(x / 10).toFixed(2)}%;--map-y:${(y / 5).toFixed(2)}%;--pulse-size:${size.toFixed(1)}px" title="${escapeHtml(title)}"><i></i></span>`;
}

function flowPath(flow, index) {
  const origin = mapCoordinates(flow.origin_country);
  const target = mapCoordinates(flow.target_country);
  if (flow.origin_country === flow.target_country) {
    return `<path class="map-flow" data-flow-index="${index}" d="M${origin.x.toFixed(1)},${origin.y.toFixed(1)} C${(origin.x - 34).toFixed(1)},${(origin.y - 48).toFixed(1)} ${(origin.x + 34).toFixed(1)},${(origin.y - 48).toFixed(1)} ${origin.x.toFixed(1)},${(origin.y - 2).toFixed(1)}" />`;
  }
  const distance = Math.hypot(target.x - origin.x, target.y - origin.y);
  const controlX = (origin.x + target.x) / 2;
  const controlY = Math.max(12, Math.min(origin.y, target.y) - Math.max(28, distance * .16));
  return `<path class="map-flow" data-flow-index="${index}" d="M${origin.x.toFixed(1)},${origin.y.toFixed(1)} Q${controlX.toFixed(1)},${controlY.toFixed(1)} ${target.x.toFixed(1)},${target.y.toFixed(1)}" />`;
}

function setLivePanelText({ provider, updated, kicker, title, feedKicker, feedTitle, feedStatus, caption }) {
  document.querySelector('#live-map-provider').textContent = provider;
  document.querySelector('#live-map-updated').textContent = updated;
  document.querySelector('#live-map-kicker').textContent = kicker;
  document.querySelector('#live-map-title').textContent = title;
  document.querySelector('#live-feed-kicker').textContent = feedKicker;
  document.querySelector('#live-feed-title').textContent = feedTitle;
  document.querySelector('#live-feed-status').textContent = feedStatus;
  document.querySelector('#live-map-caption').innerHTML = caption;
}

function renderSourceMap() {
  const data = liveDshieldData;
  if (data?.error) {
    if (liveActivityTimer) clearInterval(liveActivityTimer);
    document.querySelector('#live-threat-map').innerHTML = '<p class="chart-empty error">DShield source geography is unavailable.</p>';
    document.querySelector('#live-attacker-feed').innerHTML = '<p class="chart-empty error">Source activity is unavailable.</p>';
    return;
  }
  if (!data?.generated_at) {
    document.querySelector('#live-threat-map').innerHTML = '<p class="loading">Loading DShield source geography…</p>';
    document.querySelector('#live-attacker-feed').innerHTML = '<p class="loading">Loading source activity…</p>';
    return;
  }
  const attackers = (data.top_attackers || []).slice(0, 12);
  const mapped = attackers.filter((item) => item.country && countryCentroids[item.country]);
  const countryTotals = Object.values(attackers.reduce((totals, item) => {
    if (!item.country) return totals;
    totals[item.country] ||= { code: item.country, reports: 0, sources: 0 };
    totals[item.country].reports += Number(item.reports) || 0;
    totals[item.country].sources += 1;
    return totals;
  }, {})).sort((a, b) => b.reports - a.reports);
  const mappedCountries = countryTotals.filter((item) => countryCentroids[item.code]);
  const maxReports = Math.max(...mappedCountries.map((item) => item.reports), 1);
  const markers = mappedCountries.map((item) => mapPulse(
    item.code,
    12 + Math.sqrt(item.reports / maxReports) * 22,
    'source',
    `${countryName(item.code)}: ${number(item.sources)} sources · ${number(item.reports)} reports`,
  )).join('');
  document.querySelector('#live-threat-map').innerHTML = mapped.length
    ? `<div class="map-canvas">${accurateWorldMapSvg()}${markers}</div><div class="map-legend"><span><i></i>${number(mappedCountries.length)} source-country markers</span><span>${number(mapped.length)} mapped source IPs</span></div>`
    : '<p class="chart-empty">Source geography is temporarily unavailable.</p>';
  document.querySelector('#live-attacker-feed').innerHTML = attackers.length ? attackers.map((item, index) => `
    <article class="live-feed-row" data-feed-index="${index}">
      <span class="feed-sequence">${String(index + 1).padStart(2, '0')}</span>
      <div><strong>${escapeHtml(item.ip)}</strong><span>${escapeHtml(item.country ? countryName(item.country) : 'Location unavailable')}${item.as_name ? ` · ${escapeHtml(item.as_name)}` : ''}</span></div>
      <div class="feed-volume"><strong>${number(item.reports)}</strong><span>reports</span></div>
    </article>`).join('') : '<p class="chart-empty">No current source activity was returned.</p>';
  setLivePanelText({
    provider: 'Hourly DShield snapshot', updated: `Updated ${formatDateTime(data.generated_at)}`,
    kicker: 'Source infrastructure', title: 'Reported source geography',
    feedKicker: 'Activity feed', feedTitle: 'Top reported sources', feedStatus: 'Replaying',
    caption: '<strong>Pulses represent reported source countries, not targets.</strong> They group current top source IPs at country centroids and may represent scanners, proxies, compromised hosts, or research systems—not confirmed attacker locations or individual attack events.',
  });
  startLiveActivity(attackers);
}

function renderTargetMap() {
  const data = liveRadarData;
  if (!data) {
    document.querySelector('#live-threat-map').innerHTML = '<p class="loading">Loading Cloudflare Radar target geography…</p>';
    document.querySelector('#live-attacker-feed').innerHTML = '<p class="loading">Loading target rankings…</p>';
    return;
  }
  if (data.error || !data.targets?.length) {
    if (liveActivityTimer) clearInterval(liveActivityTimer);
    document.querySelector('#live-threat-map').innerHTML = '<p class="chart-empty error">Cloudflare Radar target geography is unavailable.</p>';
    document.querySelector('#live-attacker-feed').innerHTML = '<p class="chart-empty error">Target rankings are unavailable.</p>';
    return;
  }
  const targets = data.targets.filter((item) => countryCentroids[item.country]);
  const maxValue = Math.max(...targets.map((item) => Number(item.value) || 0), 1);
  const markers = targets.map((item) => mapPulse(
    item.country,
    12 + Math.sqrt(item.value / maxValue) * 22,
    'target',
    `${item.country_name}: ${number(item.value)}% of observed layer 7 attacks`,
  )).join('');
  document.querySelector('#live-threat-map').innerHTML = targets.length
    ? `<div class="map-canvas">${accurateWorldMapSvg()}${markers}</div><div class="map-legend"><span><i class="target-key"></i>${number(targets.length)} target-country markers</span><span>Share of mitigated requests</span></div>`
    : '<p class="chart-empty">Target geography is temporarily unavailable.</p>';
  const feedItems = targets.map((item) => ({ ...item, countries: [item.country] }));
  document.querySelector('#live-attacker-feed').innerHTML = targets.map((item, index) => `
    <article class="live-feed-row" data-feed-index="${index}">
      <span class="feed-sequence">${String(item.rank).padStart(2, '0')}</span>
      <div><strong>${escapeHtml(item.country_name)}</strong><span>${escapeHtml(item.country)} · Target location</span></div>
      <div class="feed-volume"><strong>${number(item.value)}%</strong><span>share</span></div>
    </article>`).join('');
  setLivePanelText({
    provider: 'Cloudflare Radar · 24-hour view', updated: `Updated ${formatDateTime(data.generated_at)}`,
    kicker: 'Target geography', title: 'Top targeted countries',
    feedKicker: 'Target ranking', feedTitle: 'Leading target locations', feedStatus: 'Replaying',
    caption: '<strong>Pulses represent target countries, not individual target IPs.</strong> Cloudflare assigns target geography using the attacked zone’s billing country; values are each country’s percentage of observed mitigated layer 7 requests.',
  });
  startLiveActivity(feedItems);
}

function renderFlowMap() {
  const data = liveRadarData;
  if (!data) {
    document.querySelector('#live-threat-map').innerHTML = '<p class="loading">Loading Cloudflare Radar attack paths…</p>';
    document.querySelector('#live-attacker-feed').innerHTML = '<p class="loading">Loading observed flows…</p>';
    return;
  }
  if (data.error || !data.flows?.length) {
    if (liveActivityTimer) clearInterval(liveActivityTimer);
    document.querySelector('#live-threat-map').innerHTML = '<p class="chart-empty error">Cloudflare Radar attack paths are unavailable.</p>';
    document.querySelector('#live-attacker-feed').innerHTML = '<p class="chart-empty error">Observed flow rankings are unavailable.</p>';
    return;
  }
  const flows = data.flows.filter((item) => countryCentroids[item.origin_country] && countryCentroids[item.target_country]);
  const countries = [...new Set(flows.flatMap((item) => [item.origin_country, item.target_country]))];
  const origins = new Set(flows.map((item) => item.origin_country));
  const targets = new Set(flows.map((item) => item.target_country));
  const paths = flows.map(flowPath).join('');
  const markers = countries.map((code) => mapPulse(
    code, 14, targets.has(code) ? 'target flow-node' : 'source flow-node',
    `${countryName(code)}: ${origins.has(code) ? 'origin' : ''}${origins.has(code) && targets.has(code) ? ' and ' : ''}${targets.has(code) ? 'target' : ''}`,
  )).join('');
  document.querySelector('#live-threat-map').innerHTML = flows.length
    ? `<div class="map-canvas">${accurateWorldMapSvg()}<svg class="map-flow-layer" viewBox="0 0 1000 500" aria-hidden="true">${paths}</svg>${markers}</div><div class="map-legend"><span><i class="flow-key"></i>${number(flows.length)} ranked country flows</span><span>Origin → target</span></div>`
    : '<p class="chart-empty">Attack-path geography is temporarily unavailable.</p>';
  const feedItems = flows.map((item) => ({ ...item, countries: [item.origin_country, item.target_country] }));
  document.querySelector('#live-attacker-feed').innerHTML = flows.map((item, index) => `
    <article class="live-feed-row" data-feed-index="${index}">
      <span class="feed-sequence">${String(item.rank).padStart(2, '0')}</span>
      <div><strong>${escapeHtml(item.origin_name)} → ${escapeHtml(item.target_name)}</strong><span>${escapeHtml(item.origin_country)} origin · ${escapeHtml(item.target_country)} target</span></div>
      <div class="feed-volume"><strong>${number(item.value)}%</strong><span>share</span></div>
    </article>`).join('');
  setLivePanelText({
    provider: 'Cloudflare Radar · 24-hour view', updated: `Updated ${formatDateTime(data.generated_at)}`,
    kicker: 'Attack paths', title: 'Leading origin-to-target flows',
    feedKicker: 'Ranked paths', feedTitle: 'Top observed flows', feedStatus: 'Replaying',
    caption: '<strong>Lines connect Cloudflare-observed origin and target country pairs from the same dataset.</strong> They represent aggregate shares of mitigated layer 7 requests over 24 hours—not individual live attacks or the location of a human operator.',
  });
  startLiveActivity(feedItems);
}

function renderThreatMapView() {
  document.querySelectorAll('[data-map-view]').forEach((button) => button.setAttribute('aria-pressed', String(button.dataset.mapView === liveMapView)));
  if (liveMapView === 'target') renderTargetMap();
  else if (liveMapView === 'flow') renderFlowMap();
  else renderSourceMap();
}

function renderLiveThreatStage(data) {
  liveDshieldData = data;
  const attackers = (data.top_attackers || []).slice(0, 12);
  const countryTotals = Object.values(attackers.reduce((totals, item) => {
    if (!item.country) return totals;
    totals[item.country] ||= { code: item.country, reports: 0, sources: 0 };
    totals[item.country].reports += Number(item.reports) || 0;
    totals[item.country].sources += 1;
    return totals;
  }, {})).sort((a, b) => b.reports - a.reports);
  document.querySelector('#live-country-bars').innerHTML = countryTotals.length
    ? barRows(countryTotals.slice(0, 6), (item) => item.reports, (item) => countryName(item.code))
    : '<p class="chart-empty">Country totals are unavailable.</p>';
  const ports = (data.top_ports || []).slice(0, 6);
  document.querySelector('#live-port-bars').innerHTML = ports.length
    ? barRows(ports, (item) => item.records, (item) => `${item.port} · ${portNames[item.port] || 'Other'}`)
    : '<p class="chart-empty">Targeted-port totals are unavailable.</p>';
  document.querySelector('#live-port-period').textContent = data.top_ports_date
    ? `Service targeting · DShield · ${formatDate(data.top_ports_date)}` : 'Service targeting · DShield';
  renderThreatMapView();
}

function renderCweCards(items) {
  document.querySelector('#weakness-grid').innerHTML = items.map((item, index) => {
    const description = cleanText(item.Description || 'No description available.');
    const detailId = `cwe-${item.ID}-description`;
    const mappings = (item.owasp || []).map((category) => `<a class="data-badge" href="${escapeHtml(category.url)}" target="_blank" rel="noreferrer">OWASP ${escapeHtml(category.code)} · #${category.rank}</a>`).join('');
    return `<article class="weakness-card ranked-card">
      <div class="rank-number">${String(index + 1).padStart(2, '0')}</div>
      <header><span>CWE-${escapeHtml(item.ID)}</span><span class="status">Score ${item.threat_score}</span></header>
      <div class="badge-row">${mappings || '<span class="data-badge muted-badge">No OWASP Top 10 mapping</span>'}</div>
      <h3>${escapeHtml(item.Name || 'Unnamed weakness')}</h3><p>${escapeHtml(description.slice(0, 180))}${description.length > 180 ? '…' : ''}</p>
      ${description.length > 180 ? `<button class="desc-toggle" type="button" aria-expanded="false" aria-controls="${detailId}">Full description <span>↓</span></button><p class="full-description" id="${detailId}" hidden>${escapeHtml(description)}</p>` : ''}
      <footer>${item.kev_count} KEVs · ${item.ransomware_count} ransomware · EPSS ${item.epss_percentile}%</footer>
    </article>`;
  }).join('');
}

function renderCveCards(items) {
  document.querySelector('#cve-grid').innerHTML = items.map((item, index) => {
    const description = cleanText(item.description || item.short_description || item.required_action || 'No description available.');
    const cwes = (item.cwes || []).map((cwe) => `<span class="data-badge">${escapeHtml(cwe)}</span>`).join('');
    return `<article class="weakness-card ranked-card cve-card">
      <div class="rank-number">${String(index + 1).padStart(2, '0')}</div>
      <header><a href="https://nvd.nist.gov/vuln/detail/${encodeURIComponent(item.id)}" target="_blank" rel="noreferrer">${escapeHtml(item.id)} ↗</a><span class="status">Score ${item.threat_score}</span></header>
      <div class="badge-row"><span class="data-badge kev-badge">Actively exploited</span>${item.ransomware ? '<span class="data-badge danger-badge">Ransomware</span>' : ''}${item.cvss_severity ? `<span class="data-badge">CVSS ${escapeHtml(item.cvss_severity)}</span>` : ''}${cwes}</div>
      <p class="product-line">${escapeHtml(item.vendor)} / ${escapeHtml(item.product)}</p>
      <h3>${escapeHtml(item.name || item.id)}</h3><p>${escapeHtml(description.slice(0, 200))}${description.length > 200 ? '…' : ''}</p>
      <footer>EPSS ${item.epss_probability}% · CVSS ${item.cvss_score || 'N/A'} · Added ${formatDate(item.date_added)}</footer>
    </article>`;
  }).join('');
}

function renderRansomwareCards(items) {
  document.querySelector('#ransomware-grid').innerHTML = items.map((item, index) => {
    const momentum = Number(item.recent_7d_count || 0) - Number(item.previous_7d_count || 0);
    const claims = (item.recent_victims || []).map((claim) => `<li><span>${escapeHtml(claim.title)}</span><time datetime="${escapeHtml(claim.discovered)}">${formatDate(claim.discovered)}</time></li>`).join('');
    return `<article class="weakness-card ranked-card ransomware-card">
      <div class="rank-number">${String(index + 1).padStart(2, '0')}</div>
      <header><span>RansomLook activity</span><span class="status">${number(item.share_percentage)}% share</span></header>
      <div class="badge-row"><span class="data-badge danger-badge">${number(item.recent_7d_count)} claims · 7d</span><span class="data-badge ${momentum > 0 ? 'kev-badge' : 'muted-badge'}">Momentum ${momentum > 0 ? '+' : ''}${number(momentum)}</span></div>
      <h3>${escapeHtml(displayGroupName(item.name))}</h3>
      <p>Most recently observed public victim claims:</p>
      ${claims ? `<ul class="claim-list">${claims}</ul>` : '<p class="chart-empty">No recent claim titles were returned.</p>'}
      <footer>${number(item.claim_count)} claims in 30 days · Last seen ${formatDateTime(item.last_seen)}</footer>
    </article>`;
  }).join('');
}

function barRows(items, value, label, maxValue = null) {
  const maximum = maxValue || Math.max(...items.map(value), 1);
  return items.map((item) => {
    const amount = Number(value(item)) || 0;
    const width = Math.max(2, Math.min(100, amount / maximum * 100));
    return `<div class="bar-row"><div class="bar-label"><span>${escapeHtml(label(item))}</span><strong>${amount.toLocaleString()}</strong></div><div class="bar-track"><span style="width:${width}%"></span></div></div>`;
  }).join('');
}

function overviewCard({ domain, status, title, summary, stats, chartTitle, chart, route }) {
  return `<article class="overview-card" data-route="${escapeHtml(route)}" role="link" tabindex="0" aria-label="Open ${escapeHtml(domain)} intelligence">
    <div class="overview-data">
      <div class="overview-domain"><p class="eyebrow"><span class="live-dot"></span>${escapeHtml(domain)}</p><span class="status">${escapeHtml(status)}</span></div>
      <h2>${escapeHtml(title)}</h2>
      <p class="overview-summary">${escapeHtml(summary)}</p>
      <div class="overview-stats">${stats.map((item) => `<div class="overview-stat"><strong>${escapeHtml(item.value)}</strong><span>${escapeHtml(item.label)}</span></div>`).join('')}</div>
      <a class="overview-link" href="#${escapeHtml(route)}" data-route="${escapeHtml(route)}">Open ${escapeHtml(domain)} intelligence →</a>
    </div>
    <div class="overview-chart"><p class="eyebrow">Current snapshot</p><h3>${escapeHtml(chartTitle)}</h3>${chart}</div>
  </article>`;
}

function overviewPlaceholder(domain, message = 'Loading live snapshot…') {
  return `<article class="overview-card overview-loading"><p class="loading"><strong>${escapeHtml(domain)}</strong><br />${escapeHtml(message)}</p></article>`;
}

function renderOverview() {
  const cards = [];
  const ransomware = overviewState.ransomware;
  if (ransomware?.error) {
    cards.push(overviewPlaceholder('Ransomware', ransomware.error));
  } else if (ransomware?.items?.length) {
    const top = ransomware.items[0];
    cards.push(overviewCard({
      domain: 'Ransomware', status: 'RansomLook · 30 days', route: 'ransomware-watchlist',
      title: displayGroupName(top.name),
      summary: `${number(top.claim_count)} unique public victim claims were observed for the leading group during the rolling ${number(ransomware.window_days)}-day window. Claims are source-reported and not independently confirmed.`,
      stats: [
        { value: number(top.claim_count), label: '30-day claims' },
        { value: number(top.recent_7d_count), label: 'Latest seven days' },
        { value: `${number(top.share_percentage)}%`, label: 'Share of all claims' },
      ],
      chartTitle: 'Top five groups by claims',
      chart: barRows(ransomware.items.slice(0, 5), (item) => item.claim_count, (item) => displayGroupName(item.name)),
    }));
  } else cards.push(overviewPlaceholder('Ransomware'));

  const apt = overviewState.apt;
  if (apt?.error) {
    cards.push(overviewPlaceholder('APT actors', apt.error));
  } else if (apt?.items?.length) {
    const countryCounts = Object.entries(apt.items.reduce((counts, item) => {
      if (item.country_code) counts[item.country_code] = (counts[item.country_code] || 0) + 1;
      return counts;
    }, {})).sort((a, b) => b[1] - a[1]).slice(0, 5);
    cards.push(overviewCard({
      domain: 'APT actors', status: 'MISP Galaxy catalog', route: 'apt-catalog',
      title: `${number(apt.actor_count)} attributed profiles`,
      summary: 'A searchable public catalog of country-attributed and suspected state-linked threat actors, aliases, target sectors, and supporting references.',
      stats: [
        { value: number(apt.country_count), label: 'Countries represented' },
        { value: number(apt.suspected_sponsor_count), label: 'Sponsor claims' },
        { value: '24h', label: 'Refresh interval' },
      ],
      chartTitle: 'Largest country attributions',
      chart: countryCounts.length ? barRows(countryCounts, (item) => item[1], (item) => countryName(item[0])) : '<p class="chart-empty">Country metadata is unavailable.</p>',
    }));
  } else cards.push(overviewPlaceholder('APT actors'));

  const cwe = overviewState.cwe;
  if (cwe?.error) {
    cards.push(overviewPlaceholder('CWE', cwe.error));
  } else if (cwe?.items?.length) {
    const top = cwe.items[0];
    const name = top.Name && top.Name !== `CWE-${top.ID}` ? ` · ${top.Name}` : '';
    cards.push(overviewCard({
      domain: 'CWE', status: 'Weakness patterns', route: 'cwe-watchlist',
      title: `CWE-${top.ID}${name}`,
      summary: cleanText(top.Description || 'The weakness patterns most connected to active exploitation and near-term exploit probability.').slice(0, 220),
      stats: [
        { value: number(top.threat_score), label: 'Threat score' },
        { value: number(top.kev_count), label: 'Known exploited CVEs' },
        { value: `${number(top.epss_percentile)}%`, label: 'EPSS percentile' },
      ],
      chartTitle: 'Top five weakness scores',
      chart: barRows(cwe.items.slice(0, 5), (item) => item.threat_score, (item) => `CWE-${item.ID}`, 100),
    }));
  } else cards.push(overviewPlaceholder('CWE'));

  const cve = overviewState.cve;
  if (cve?.error) {
    cards.push(overviewPlaceholder('CVE', cve.error));
  } else if (cve?.items?.length) {
    const top = cve.items[0];
    cards.push(overviewCard({
      domain: 'CVE', status: 'Active vulnerabilities', route: 'cve-watchlist',
      title: top.id,
      summary: cleanText(top.name || top.description || top.short_description || 'Recently exploited vulnerabilities ranked using exploitation, ransomware, probability, recency, and severity signals.').slice(0, 220),
      stats: [
        { value: number(top.threat_score), label: 'Threat score' },
        { value: `${number(top.epss_probability)}%`, label: 'EPSS probability' },
        { value: top.cvss_score ? number(top.cvss_score) : 'N/A', label: 'CVSS base score' },
      ],
      chartTitle: 'Top five exploit probabilities',
      chart: barRows(cve.items.slice(0, 5), (item) => item.epss_probability, (item) => item.id, 100),
    }));
  } else cards.push(overviewPlaceholder('CVE'));

  const dshield = overviewState.dshield;
  if (dshield?.error) {
    cards.push(overviewPlaceholder('Honeypots', dshield.error));
  } else if (dshield?.generated_at) {
    const topAttacker = dshield.top_attackers?.[0];
    const topPort = dshield.top_ports?.[0];
    cards.push(overviewCard({
      domain: 'Honeypots', status: 'DShield community feed', route: 'dshield-activity',
      title: `${number(dshield.indicator_total)} observed indicators`,
      summary: `Current attacker, service, SSH, and web-scanning signals reported by the global DShield sensor community. Last refreshed ${formatDateTime(dshield.generated_at)}.`,
      stats: [
        { value: number(topAttacker?.reports), label: 'Top source reports' },
        { value: topPort ? `${topPort.port} · ${portNames[topPort.port] || 'Other'}` : 'N/A', label: 'Top targeted port' },
        { value: number(dshield.indicator_counts?.ssh), label: 'SSH indicators' },
      ],
      chartTitle: 'Top five targeted ports',
      chart: dshield.top_ports?.length ? barRows(dshield.top_ports.slice(0, 5), (item) => item.records, (item) => `${item.port} · ${portNames[item.port] || 'Other'}`) : '<p class="chart-empty">Port data is unavailable.</p>',
    }));
  } else cards.push(overviewPlaceholder('Honeypots'));

  document.querySelector('#overview-cards').innerHTML = cards.join('');
}

document.querySelector('#overview-cards').addEventListener('click', (event) => {
  const link = event.target.closest('[data-route]');
  if (!link) return;
  event.preventDefault();
  showView(link.dataset.route);
});
document.querySelector('#overview-cards').addEventListener('keydown', (event) => {
  if (event.key !== 'Enter' && event.key !== ' ') return;
  const card = event.target.closest('.overview-card[data-route]');
  if (!card) return;
  event.preventDefault();
  showView(card.dataset.route);
});

const lineColors = ['#ff5c35', '#1f8a70', '#7c5cff', '#d49b00', '#3273dc'];

function formatMonth(month) {
  const [year, monthNumber] = month.split('-').map(Number);
  return new Intl.DateTimeFormat('en-US', { month: 'short', year: '2-digit', timeZone: 'UTC' })
    .format(new Date(Date.UTC(year, monthNumber - 1, 1)));
}

function formatDay(value) {
  const [year, month, day] = value.split('-').map(Number);
  return new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' })
    .format(new Date(Date.UTC(year, month - 1, day)));
}

function lineChart(series, ariaLabel, yAxisLabel = 'Cumulative KEV count', xAxisLabel = 'Catalog addition month', formatBucket = formatMonth) {
  const validSeries = series.filter((item) => item.points?.length);
  if (!validSeries.length) return '<p class="chart-empty">Timeline data is unavailable.</p>';

  const width = 720;
  const height = 300;
  const plot = { left: 68, right: 18, top: 18, bottom: 62 };
  const points = validSeries[0].points;
  const maxValue = Math.max(1, ...validSeries.flatMap((item) => item.points.map((point) => Number(point.count) || 0)));
  const niceMax = Math.ceil(maxValue / Math.max(1, Math.pow(10, Math.floor(Math.log10(maxValue))))) * Math.max(1, Math.pow(10, Math.floor(Math.log10(maxValue))));
  const x = (index) => plot.left + index * (width - plot.left - plot.right) / Math.max(1, points.length - 1);
  const y = (value) => plot.top + (niceMax - value) * (height - plot.top - plot.bottom) / niceMax;
  const ticks = [0, .25, .5, .75, 1];
  const labelIndexes = [...new Set([0, Math.floor((points.length - 1) / 2), points.length - 1])];

  const grid = ticks.map((tick) => {
    const value = Math.round(niceMax * tick);
    return `<g><line class="line-grid" x1="${plot.left}" y1="${y(value)}" x2="${width - plot.right}" y2="${y(value)}"></line><text class="line-axis-label" x="${plot.left - 10}" y="${y(value) + 4}" text-anchor="end">${value}</text></g>`;
  }).join('');
  const xLabels = labelIndexes.map((index) => `<text class="line-axis-label" x="${x(index)}" y="${height - 32}" text-anchor="middle">${formatBucket(points[index].month)}</text>`).join('');
  const plotMiddleY = (plot.top + height - plot.bottom) / 2;
  const axisTitles = `<text class="line-axis-title" x="${(plot.left + width - plot.right) / 2}" y="${height - 6}" text-anchor="middle">${escapeHtml(xAxisLabel)}</text><text class="line-axis-title" x="14" y="${plotMiddleY}" text-anchor="middle" transform="rotate(-90 14 ${plotMiddleY})">${escapeHtml(yAxisLabel)}</text>`;
  const paths = validSeries.map((item, seriesIndex) => {
    const color = lineColors[seriesIndex % lineColors.length];
    const path = item.points.map((point, index) => `${index ? 'L' : 'M'} ${x(index).toFixed(1)} ${y(Number(point.count) || 0).toFixed(1)}`).join(' ');
    const markers = item.points.map((point, index) => `<circle cx="${x(index)}" cy="${y(Number(point.count) || 0)}" r="3" fill="${color}"><title>${escapeHtml(item.label)} · ${formatBucket(point.month)}: ${Number(point.count).toLocaleString()}</title></circle>`).join('');
    return `<g><path class="line-series" d="${path}" stroke="${color}"></path>${markers}</g>`;
  }).join('');
  const legend = validSeries.map((item, index) => `<span><i style="--series-color:${lineColors[index % lineColors.length]}"></i>${escapeHtml(item.label)}</span>`).join('');

  return `<div class="line-chart"><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${escapeHtml(ariaLabel)}">${grid}${xLabels}${axisTitles}${paths}</svg><div class="line-legend">${legend}</div></div>`;
}

