  const portRows = ports.map((item) => `<tr><td>${escapeHtml(item.port)}</td><td>${escapeHtml(portNames[item.port] || 'Other')}</td><td>${number(item.records)}</td><td>${number(item.sources)}</td></tr>`).join('');
